function second(a) {
  let max=null, next=null;
  for(const x of a) {
    if(max===null || x>max) {next=max;max=x;}
    else if(x<max && (next===null||x>next)) next=x;
  }
  return next;
}

static Integer second(int[] a) {
  Integer max=null,next=null;
  for(int x:a) {
    if(max==null||x>max) {next=max;max=x;}
    else if(x<max&&(next==null||x>next)) next=x;
  }
  return next;
}
